CREATE TYPE "Role" AS ENUM ('TEAM_MEMBER','MANAGER','ADMIN');
CREATE TYPE "ReportStatus" AS ENUM ('DRAFT','SUBMITTED','NEEDS_CORRECTION','APPROVED');
CREATE TYPE "Priority" AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TYPE "TaskStatus" AS ENUM ('NOT_STARTED','IN_PROGRESS','COMPLETED','BLOCKED');
CREATE TYPE "BlockerStatus" AS ENUM ('OPEN','RESOLVED');
CREATE TYPE "ReviewAction" AS ENUM ('APPROVED','CHANGES_REQUESTED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'TEAM_MEMBER',"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Project" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"description" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Report" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"projectId" TEXT NOT NULL,"weekStartDate" DATE NOT NULL,"weekEndDate" DATE NOT NULL,"status" "ReportStatus" NOT NULL DEFAULT 'DRAFT',"notes" TEXT,"links" TEXT[] DEFAULT ARRAY[]::TEXT[],"submittedAt" TIMESTAMP(3),"approvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Report_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id"),CONSTRAINT "Report_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id"),CONSTRAINT "Report_userId_projectId_weekStartDate_key" UNIQUE ("userId","projectId","weekStartDate"));
CREATE TABLE "ReportTask" ("id" TEXT PRIMARY KEY,"reportId" TEXT NOT NULL,"name" TEXT NOT NULL,"priority" "Priority" NOT NULL,"plannedPercentage" INTEGER NOT NULL,"actualPercentage" INTEGER NOT NULL,"status" "TaskStatus" NOT NULL,"plannedTime" DOUBLE PRECISION NOT NULL,"actualTime" DOUBLE PRECISION NOT NULL,"deliverable" TEXT NOT NULL,CONSTRAINT "ReportTask_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "Report"("id") ON DELETE CASCADE);
CREATE TABLE "NextWeekTask" ("id" TEXT PRIMARY KEY,"reportId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"priority" "Priority" NOT NULL,CONSTRAINT "NextWeekTask_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "Report"("id") ON DELETE CASCADE);
CREATE TABLE "Blocker" ("id" TEXT PRIMARY KEY,"reportId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"isKeyIssue" BOOLEAN NOT NULL DEFAULT false,"status" "BlockerStatus" NOT NULL DEFAULT 'OPEN',CONSTRAINT "Blocker_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "Report"("id") ON DELETE CASCADE);
CREATE TABLE "Achievement" ("id" TEXT PRIMARY KEY,"reportId" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"isKeyAchievement" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "Achievement_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "Report"("id") ON DELETE CASCADE);
CREATE TABLE "WorkHour" ("id" TEXT PRIMARY KEY,"reportId" TEXT NOT NULL,"workType" TEXT NOT NULL,"hours" DOUBLE PRECISION NOT NULL,CONSTRAINT "WorkHour_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "Report"("id") ON DELETE CASCADE);
CREATE TABLE "ReportVersion" ("id" TEXT PRIMARY KEY,"reportId" TEXT NOT NULL,"versionNumber" INTEGER NOT NULL,"snapshot" JSONB NOT NULL,"submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReportVersion_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "Report"("id") ON DELETE CASCADE,CONSTRAINT "ReportVersion_reportId_versionNumber_key" UNIQUE ("reportId","versionNumber"));
CREATE TABLE "Review" ("id" TEXT PRIMARY KEY,"reportId" TEXT NOT NULL,"reviewerId" TEXT NOT NULL,"versionId" TEXT NOT NULL,"action" "ReviewAction" NOT NULL,"comment" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Review_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "Report"("id") ON DELETE CASCADE,CONSTRAINT "Review_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User"("id"),CONSTRAINT "Review_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "ReportVersion"("id"));
CREATE TABLE "ActivityLog" ("id" TEXT PRIMARY KEY,"actorId" TEXT,"action" TEXT NOT NULL,"description" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
